gSt(){return"\u0936\u0947\u0937 \u0930\u093e\u0936\u093f"},
gGI(){return"\u092b\u093f\u0930 \u0938\u0947 \u092d\u0930\u0947\u0902"},
gSC(){return"\u0916\u0930\u094d\u091a \u0926\u0930\u094d\u091c \u0915\u0930\u0947\u0902"},
gSB(){return"\u0907\u0938 \u092b\u0902\u0921 \u0938\u0947 \u0905\u092d\u0940 \u0924\u0915 \u0915\u094b\u0908 \u0916\u0930\u094d\u091a \u0926\u0930\u094d\u091c \u0928\u0939\u0940\u0902 \u0939\u0941\u0906 \u0939\u0948\u0964"},
